import {readFileSync} from 'node:fs';
import {join} from 'node:path';
import {createHash} from 'node:crypto';
import {sitesEvidenceFixture,fileBucket} from './sites-evidence.js';
import {CanonicalSourceInspector} from '../../src/canonical-source-inspector.js';
